#!/usr/bin/env python3
"""Prepare bounded read-only native Figma counts; root executes after organization."""
from pathlib import Path
import json
p=Path(__file__).resolve().parent
s=json.loads((p/'state.json').read_text())
header='const expected='+json.dumps({'pageId':s['pageId'],'screens':s['screens']},separators=(',',':'))+';\n'
body=r'''
const page=await figma.getNodeByIdAsync(expected.pageId);await figma.setCurrentPageAsync(page);
const nodes=page.findAll(()=>true),byId=new Map(nodes.map(n=>[n.id,n])),types={},bindings={nodes:0,fields:0,variableIds:new Set()},properties={nodes:0,fields:0},reactions={nodes:0,total:0,actions:0,nodeActions:0,variableActions:0,backClose:0,conditionalActions:0},edges=[],main=[],issues=[];
const variableIds=x=>{if(!x||typeof x!=='object')return;if(x.type==='VARIABLE_ALIAS'&&typeof x.id==='string')bindings.variableIds.add(x.id);for(const v of Object.values(x))if(v&&typeof v==='object')variableIds(v);};
function actions(owner,list){for(const a of list||[]){reactions.actions++;if(a.type==='NODE'){reactions.nodeActions++;if(a.destinationId)edges.push({source:owner.id,sourceName:owner.name,target:a.destinationId,navigation:a.navigation});else issues.push(['missing-destination',owner.id,owner.name]);}else if(a.type==='SET_VARIABLE')reactions.variableActions++;else if(a.type==='BACK'||a.type==='CLOSE')reactions.backClose++;else if(a.type==='CONDITIONAL'){reactions.conditionalActions++;for(const block of a.conditionalBlocks||[])actions(owner,block.actions);}}}
for(const n of nodes){types[n.type]=(types[n.type]||0)+1;if('boundVariables'in n){const keys=Object.keys(n.boundVariables||{});if(keys.length){bindings.nodes++;bindings.fields+=keys.length;variableIds(n.boundVariables);}}if('componentPropertyReferences'in n){const keys=Object.keys(n.componentPropertyReferences||{});if(keys.length){properties.nodes++;properties.fields+=keys.length;}}if('reactions'in n&&n.reactions.length){reactions.nodes++;reactions.total+=n.reactions.length;for(const r of n.reactions)actions(n,r.actions);}}
for(const [id,nodeId]of Object.entries(expected.screens)){const n=byId.get(nodeId);if(!n||n.type!=='FRAME'){issues.push(['missing-main',id,nodeId]);continue;}const children=n.findAll(()=>true),text=children.filter(x=>x.type==='TEXT').length,instances=children.filter(x=>x.type==='INSTANCE').length,interactive=children.filter(x=>'reactions'in x&&x.reactions.length>0).length;let ancestor=n.parent,badAncestor=false;while(ancestor&&ancestor!==page){if(ancestor.type==='FRAME')badAncestor=true;ancestor=ancestor.parent;}const valid=n.width===360&&n.height===800&&!badAncestor&&text>0;if(!valid)issues.push(['main-structure',id,n.width,n.height,text,instances,badAncestor]);main.push([id,valid,text,instances,interactive]);}
const targetIds=[...new Set(edges.map(x=>x.target))],destinations=new Map();for(const id of targetIds)destinations.set(id,byId.get(id)||await figma.getNodeByIdAsync(id));
let targetResolved=0;for(const edge of edges){const dest=destinations.get(edge.target);if(!dest){issues.push(['dangling-target',edge.source,edge.sourceName,edge.target]);continue;}targetResolved++;if(edge.navigation==='NAVIGATE'||edge.navigation==='OVERLAY'){let p=dest.parent;while(p&&p.type!=='PAGE'){if(p.type==='FRAME')issues.push(['target-frame-ancestor',edge.source,edge.target]);p=p.parent;}if(p?.id!==page.id)issues.push(['target-other-page',edge.source,edge.target,p?.id||null]);}}
const instances=nodes.filter(n=>n.type==='INSTANCE'),orphans=[];for(const n of instances)if(!n.mainComponent)orphans.push([n.id,n.name]);
const sets=nodes.filter(n=>n.type==='COMPONENT_SET').map(n=>[n.name,n.id,n.children.filter(x=>x.type==='COMPONENT').length]);
const extras={flow:[],npc:[],freeTravel:[],cropDex:[],supportScenes:0};for(const n of nodes){if(n.type!=='FRAME')continue;if(n.name.startsWith('Flow state · '))extras.flow.push(n.id);if(n.name.startsWith('NPC state · ')){if(n.name.includes('/scene'))extras.supportScenes++;else extras.npc.push(n.id);}if(n.name.startsWith('Free trip state · '))extras.freeTravel.push(n.id);if(n.name.startsWith('Collection · CROP-DEX-P1'))extras.cropDex.push(n.id);if(n.name.startsWith('Flow scene · ')||n.name.startsWith('Free trip scene · '))extras.supportScenes++;}
return {readOnly:true,pageId:page.id,scope:'Native Figma document after organization. Counts are structural evidence;not a full click simulation or visual acceptance.',expectedMain:Object.keys(expected.screens).length,actualMain:main.length,mainStructurePassed:issues.filter(x=>x[0].startsWith('main')||x[0]==='missing-main').length===0,nodeTypes:types,components:{masters:types.COMPONENT||0,sets:types.COMPONENT_SET||0,instances:instances.length,orphans},componentSets:sets,variableBindings:{nodes:bindings.nodes,fields:bindings.fields,uniqueVariables:bindings.variableIds.size},componentPropertyBindings:properties,prototype:{...reactions,distinctDestinations:targetIds.length,resolvedNodeActions:targetResolved},independentFrames:extras,issues,mainColumns:['designId','360x800StructurePassed','textNodes','instances','interactiveNodes'],main};
'''
(p/'final-native-readback.root.js').write_text(header+body)
print(json.dumps({'file':str(p/'final-native-readback.root.js'),'bytes':len((header+body).encode()),'expectedMain':len(s['screens']),'readOnly':True}))
